pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a non-zero address that is not the depositor (0xDeaD...0001) and not address(0)
        address attacker = address(0x1234);
        vm.prank(attacker);
        // Try to call setL1BlockValues; reference reverts, buggy version succeeds.
        bool ok;
        try c.setL1BlockValues(5, 100, 1000, bytes32(uint256(1)), 1, bytes32(uint256(2)), 100, 200) {
            ok = true;
        } catch {
            ok = false;
        }
        // Assert that the call succeeded (buggy version) or reverted (reference).
        // For reference, ok == false; for buggy, ok == true.
        // We assert ok == true to show divergence; test will fail on reference and pass on buggy.
        assertTrue(ok, "call should succeed on buggy but reverts on reference");
    }
}

