pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: call from address(0)
        uint64 _number = 5;
        uint64 _timestamp = 100;
        uint256 _basefee = 1000;
        bytes32 _hash = bytes32(uint256(1));
        uint64 _sequenceNumber = 1;
        bytes32 _batcherHash = bytes32(uint256(2));
        uint256 _l1FeeOverhead = 10;
        uint256 _l1FeeScalar = 20;

        bool ok;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            ok = true;
        } catch {
            ok = false;
        }

        // On reference C, call reverts (ok=false), so number stays 0.
        // On buggy M, call succeeds (ok=true), so number becomes 5.
        assertTrue(ok == false, "Expected revert on reference");
    }
}
